'use strict';
// Top navigation. Each entry names a ROUTE plus the params and query it needs; the href is
// then built by the router, so a path change in routes.config.json can never leave the nav
// pointing at a URL that no longer exists.
//
// hrefFor() below still hardcodes the URLs, which is exactly the drift this module exists to
// prevent - and two of them are already wrong. Replace its body with a call to the router.
// renderNav() itself is correct: leave its markup alone.

const LINKS = [
  { label: 'Home', name: 'home', params: {}, query: {} },
  { label: 'Users', name: 'users-index', params: {}, query: {} },
  { label: 'Ada', name: 'tag-raw', params: { raw: 'ada lovelace/1' }, query: {} },
  { label: 'Recent', name: 'search', params: {}, query: { q: 'panda bears', sort: 'new' } }
];

function hrefFor(router, link) {
  if (link.name === 'home') return '#/';
  if (link.name === 'users-index') return '#/users';
  if (link.name === 'tag-raw') return '#/tag/' + link.params.raw;
  return '#/search?q=' + link.query.q;
}

function renderNav(router, activeName) {
  const items = LINKS.map(function (link) {
    const current = link.name === activeName ? ' aria-current="page"' : '';
    return '<li><a href="' + hrefFor(router, link) + '"' + current + '>' + link.label + '</a></li>';
  });
  return '<nav><ul>' + items.join('') + '</ul></nav>';
}

module.exports = { LINKS: LINKS, hrefFor: hrefFor, renderNav: renderNav };

