'use strict';
// QUERY RULES v1 - the single definition of query-string handling for this app.
// The router must call these; a second implementation of the same rules is a bug waiting to
// drift, so do not write one.
//
// parseQuery("a=1&a=2&b&c=x%20y&d=a+b")  ->  { a: ["1","2"], b: "", c: "x y", d: "a b" }
//   * a leading "?" is ignored; everything else is the query
//   * "+" is a space, %XX is percent-decoding, and BOTH keys and values are decoded
//   * a key with no "=" has the value ""
//   * a key that occurs more than once becomes an array of its values, in order
//   * "" and "?" parse to {}
//
// stringifyQuery({ b: "", a: ["1","2"], c: "x y" })  ->  "a=1&a=2&b=&c=x%20y"
//   * keys sorted by < on the raw key; an array emits one pair per item, in its own order
//   * encodeURIComponent for keys and values, so a space is %20 and never "+"
//   * undefined and null values are skipped entirely; {} gives ""

function decode(s) {
  try {
    return decodeURIComponent(String(s).replace(/\+/g, '%20'));
  } catch (e) {
    return String(s);
  }
}

function parseQuery(qs) {
  const out = {};
  let s = String(qs == null ? '' : qs);
  if (s.charAt(0) === '?') s = s.slice(1);
  if (s === '') return out;
  for (const part of s.split('&')) {
    if (part === '') continue;
    const eq = part.indexOf('=');
    const rawKey = eq === -1 ? part : part.slice(0, eq);
    const rawVal = eq === -1 ? '' : part.slice(eq + 1);
    const key = decode(rawKey);
    const val = decode(rawVal);
    if (!Object.prototype.hasOwnProperty.call(out, key)) {
      out[key] = val;
    } else if (Array.isArray(out[key])) {
      out[key].push(val);
    } else {
      out[key] = [out[key], val];
    }
  }
  return out;
}

function stringifyQuery(obj) {
  const pairs = [];
  const keys = Object.keys(obj || {}).sort(function (a, b) { return a < b ? -1 : a > b ? 1 : 0; });
  for (const k of keys) {
    const v = obj[k];
    if (v === undefined || v === null) continue;
    const list = Array.isArray(v) ? v : [v];
    for (const item of list) {
      if (item === undefined || item === null) continue;
      pairs.push(encodeURIComponent(k) + '=' + encodeURIComponent(item));
    }
  }
  return pairs.join('&');
}

module.exports = { parseQuery: parseQuery, stringifyQuery: stringifyQuery };

