'use strict';
// CONTRACT SPEC for the hash router.   Run:  node tests/router.spec.js
// Do not edit this file. Every message states the rule being enforced.
const assert = require('assert');
let createRouter;
try {
  createRouter = require('../src/router.js').createRouter;
} catch (e) {
  console.error('cannot load src/router.js: ' + e.message);
  console.error('src/router.js must be CommonJS ending in: module.exports = { createRouter };');
  process.exit(1);
}
const routes = require('../routes.config.json');
const nav = require('../src/nav.js');

let n = 0;
function eq(a, b, msg) { assert.strictEqual(a, b, msg + '\n  got  ' + a + '\n  want ' + b); n++; }

const r = createRouter(routes);
const show = function (res) {
  return res.name + ' {' + Object.keys(res.params).map(function (k) {
    return k + '=' + res.params[k];
  }).join(',') + '} [' + res.chain.join('>') + ']';
};

// hash -> "name {params in placeholder order} [chain from root leafwards]"
const RESOLVE = [
  ['', 'home {} [home]'],
  ['#', 'home {} [home]'],
  ['#/', 'home {} [home]'],
  ['/', 'home {} [home]'],
  ['#/users', 'users-index {} [users-section>users-index]'],
  ['#/users/', 'users-index {} [users-section>users-index]'],
  ['#/users//', 'users-index {} [users-section>users-index]'],
  ['#/users/new', 'user-new {} [users-section>user-new]'],
  ['#/users/42', 'user-overview {id=42} [users-section>user-section>user-overview]'],
  ['#/users/-3', 'user-overview {id=-3} [users-section>user-section>user-overview]'],
  ['#/users/abc', 'not-found {} [not-found]'],
  ['#/users/42/edit', 'user-edit {id=42} [users-section>user-section>user-edit]'],
  ['#/users/42/posts/7', 'user-post {id=42,postId=7} [users-section>user-section>user-post]'],
  ['#/users/42/posts/x', 'not-found {} [not-found]'],
  ['#/tag/ada-lovelace', 'tag {name=ada-lovelace} [tag]'],
  ['#/tag/42', 'tag {name=42} [tag]'],
  ['#/tag/Ada%20L', 'tag-raw {raw=Ada L} [tag-raw]'],
  ['#/files/a/b%20c/d.txt', 'files {rest=a/b c/d.txt} [files]'],
  ['#/files', 'files {rest=} [files]'],
  ['#/archive/2024', 'archive {year=2024} [archive]'],
  ['#/archive/2024/05', 'archive {year=2024,month=05} [archive]'],
  ['#/archive/20x4', 'not-found {} [not-found]'],
  ['#/archive/2024/xx', 'not-found {} [not-found]'],
  ['#/archive', 'not-found {} [not-found]'],
  ['#/nope/deep/er', 'not-found {} [not-found]'],
  ['#/search?q=a+b&q=c&sort=', 'search {} [search]']
];
for (const [hash, want] of RESOLVE) eq(show(r.resolve(hash)), want, 'resolve(' + JSON.stringify(hash) + ')');

eq(JSON.stringify(r.resolve('#/search?q=a+b&q=c&sort=').query), '{"q":["a b","c"],"sort":""}',
  'the query must come from parseQuery in src/query.js, repeated keys and all');
eq(JSON.stringify(r.resolve('#/nope?x=1').query), '{"x":"1"}',
  'a not-found result still carries the parsed query');
eq(Object.keys(r.resolve('#/users/42')).sort().join(','), 'chain,name,params,query',
  'resolve returns exactly name, params, query and chain');

// name -> href
const LINK = [
  ['home', {}, {}, '#/'],
  ['users-index', {}, {}, '#/users'],
  ['user-new', {}, {}, '#/users/new'],
  ['user-post', { id: '42', postId: '7' }, {}, '#/users/42/posts/7'],
  ['tag-raw', { raw: 'ada lovelace/1' }, {}, '#/tag/ada%20lovelace%2F1'],
  ['tag', { name: 'ada-lovelace' }, {}, '#/tag/ada-lovelace'],
  ['files', { rest: 'a/b c/d.txt' }, {}, '#/files/a/b%20c/d.txt'],
  ['files', { rest: '' }, {}, '#/files'],
  ['archive', { year: '2024' }, {}, '#/archive/2024'],
  ['archive', { year: '2024', month: '05' }, {}, '#/archive/2024/05'],
  ['search', {}, { q: 'panda bears', sort: 'new' }, '#/search?q=panda%20bears&sort=new']
];
for (const [name, params, query, want] of LINK) {
  eq(r.link(name, params, query), want, 'link(' + name + ')');
  const back = r.resolve(want);
  eq(back.name, name, 'resolve(link(' + name + ')) must land back on the same route');
  eq(JSON.stringify(back.params), JSON.stringify(params),
    'link then resolve must round-trip the params of ' + name);
}

assert.throws(function () { r.link('nope', {}, {}); }, /unknown route: nope/,
  'link on an unknown name throws "unknown route: <name>"'); n++;
assert.throws(function () { r.link('user-overview', {}, {}); }, /missing param: id/,
  'link with a required param missing throws "missing param: <name>"'); n++;
assert.throws(function () { r.link('user-overview', { id: 'abc' }, {}); }, /invalid param: id/,
  'link with a value that breaks the param constraint throws "invalid param: <name>"'); n++;
assert.throws(function () { r.link('tag', { name: 'Not A Slug' }, {}); }, /invalid param: name/,
  'the slug constraint is enforced when building a link too'); n++;
assert.throws(function () {
  createRouter([{ path: '/a/:x', name: 'p1' }, { path: '/a/:y', name: 'p2' }]);
}, /ambiguous routes: p1 and p2/, 'two leaves with the same pattern are rejected at construction'); n++;
assert.throws(function () {
  createRouter([{ path: '/x', name: 's', children: [{ path: '', name: 'i' }] },
    { path: '/x', name: 't' }]);
}, /ambiguous routes: i and t/, 'the clash is reported in depth-first declaration order'); n++;
assert.throws(function () {
  createRouter([{ path: '/a/:x<money>', name: 'm' }]);
}, /unknown constraint: money/, 'only int, slug and uuid exist as constraints'); n++;
createRouter([{ path: '/a/:x<int>', name: 'q1' }, { path: '/a/:x', name: 'q2' }]); n++;

eq(nav.renderNav(r, 'users-index'),
  '<nav><ul><li><a href="#/">Home</a></li><li><a href="#/users" aria-current="page">Users</a></li>' +
  '<li><a href="#/tag/ada%20lovelace%2F1">Ada</a></li>' +
  '<li><a href="#/search?q=panda%20bears&sort=new">Recent</a></li></ul></nav>',
  'src/nav.js hrefFor() must build every href through the router');

console.log('ok ' + n + ' assertions');
